const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const china = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'China'));
  const geom = china.geometry();

  // 2. Data Acquisition using MODIS LAI product
  const lai2000 = ee.ImageCollection('MODIS/061/MCD15A2H')
    .filterDate('2000-01-01', '2000-12-31')
    .filterBounds(geom)
    .select('Lai');

  const lai2017 = ee.ImageCollection('MODIS/061/MCD15A2H')
    .filterDate('2017-01-01', '2017-12-31')
    .filterBounds(geom)
    .select('Lai');

  const size2000 = lai2000.size().getInfo();
  const size2017 = lai2017.size().getInfo();

  console.log(`2000 Images: ${size2000}`);
  console.log(`2017 Images: ${size2017}`);

  if (size2000 === 0 || size2017 === 0) {
    console.log("Missing data for one or both years.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create annual composites (mean)
  const lai2000Mean = lai2000.mean().multiply(0.1); // Scale factor
  const lai2017Mean = lai2017.mean().multiply(0.1);

  // 4. Calculate statistics with pixel count
  const stats2000 = lai2000Mean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2017 = lai2017Mean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean2000 = stats2000.Lai_mean;
  const count2000 = stats2000.Lai_count;
  const mean2017 = stats2017.Lai_mean;
  const count2017 = stats2017.Lai_count;

  console.log(`2000 Stats: Mean LAI=${mean2000}, Pixels=${count2000}`);
  console.log(`2017 Stats: Mean LAI=${mean2017}, Pixels=${count2017}`);

  // 5. Validation & Final Answer
  if (count2000 === 0 || count2017 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean2000 === null || mean2017 === null || 
      isNaN(mean2000) || isNaN(mean2017) ||
      mean2000 < 0 || mean2017 < 0 || mean2000 > 10 || mean2017 > 10) {
    console.log("Invalid LAI values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  const change = mean2017 - mean2000;
  console.log(`LAI Change: ${change.toFixed(4)} (${((change/mean2000)*100).toFixed(2)}%)`);

  if (mean2017 > mean2000) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
